-- Empty authoritative published-policy boundary. No operating terms, IDs, versions, acceptance, or publication seed.
CREATE TABLE community_policy_documents(environment TEXT NOT NULL CHECK(environment IN ('DEV','PRD')),locale TEXT NOT NULL,document_id TEXT NOT NULL,document_version TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('SERVICE_TERMS','COMMUNITY_RULES')),content_digest TEXT NOT NULL,body_text TEXT NOT NULL,publication_state TEXT NOT NULL CHECK(publication_state IN ('DRAFT','PUBLISHED')),PRIMARY KEY(environment,locale,document_id,document_version));
CREATE TABLE community_policy_pairs(environment TEXT NOT NULL CHECK(environment IN ('DEV','PRD')),locale TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>0),references_json TEXT NOT NULL CHECK(json_valid(references_json)),policy_digest TEXT NOT NULL,publication_state TEXT NOT NULL CHECK(publication_state IN ('DRAFT','PUBLISHED')),PRIMARY KEY(environment,locale,policy_revision));
CREATE TABLE community_policy_current(environment TEXT NOT NULL,locale TEXT NOT NULL,policy_revision INTEGER NOT NULL,PRIMARY KEY(environment,locale),FOREIGN KEY(environment,locale,policy_revision) REFERENCES community_policy_pairs(environment,locale,policy_revision));
CREATE TRIGGER community_policy_documents_immutable BEFORE UPDATE ON community_policy_documents WHEN OLD.publication_state='PUBLISHED' BEGIN SELECT RAISE(ABORT,'community_policy_document_immutable'); END;
CREATE TRIGGER community_policy_pairs_immutable BEFORE UPDATE ON community_policy_pairs WHEN OLD.publication_state='PUBLISHED' BEGIN SELECT RAISE(ABORT,'community_policy_pair_immutable'); END;
CREATE TABLE community_consent_receipts(account_id TEXT NOT NULL REFERENCES accounts(id),command_id TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),PRIMARY KEY(account_id,command_id));
CREATE TABLE community_consent_current(account_id TEXT NOT NULL REFERENCES accounts(id),environment TEXT NOT NULL,locale TEXT NOT NULL,policy_revision INTEGER NOT NULL,policy_digest TEXT NOT NULL,command_id TEXT NOT NULL,accepted_at INTEGER NOT NULL CHECK(accepted_at>=0),receipt_json TEXT NOT NULL CHECK(json_valid(receipt_json)),PRIMARY KEY(account_id,environment,locale),FOREIGN KEY(account_id,command_id) REFERENCES community_consent_receipts(account_id,command_id));
-- No arbitrary retention period: consent history/account deletion classification is an operating prerequisite.
-- Published stable identities cannot be retired/reused by DELETE or SQLite REPLACE.
-- Draft preparation is separate from immutable published source; no publishing command is supplied here.
CREATE TRIGGER community_policy_documents_no_delete BEFORE DELETE ON community_policy_documents WHEN OLD.publication_state='PUBLISHED' BEGIN SELECT RAISE(ABORT,'community_policy_document_immutable'); END;
CREATE TRIGGER community_policy_pairs_no_delete BEFORE DELETE ON community_policy_pairs WHEN OLD.publication_state='PUBLISHED' BEGIN SELECT RAISE(ABORT,'community_policy_pair_immutable'); END;
CREATE TRIGGER community_policy_documents_no_replace BEFORE INSERT ON community_policy_documents WHEN EXISTS(SELECT 1 FROM community_policy_documents d WHERE d.environment=NEW.environment AND d.locale=NEW.locale AND d.document_id=NEW.document_id AND d.document_version=NEW.document_version AND d.publication_state='PUBLISHED' AND (d.kind<>NEW.kind OR d.content_digest<>NEW.content_digest OR d.body_text<>NEW.body_text OR d.publication_state<>NEW.publication_state)) BEGIN SELECT RAISE(ABORT,'community_policy_document_immutable'); END;
CREATE TRIGGER community_policy_pairs_no_replace BEFORE INSERT ON community_policy_pairs WHEN EXISTS(SELECT 1 FROM community_policy_pairs p WHERE p.environment=NEW.environment AND p.locale=NEW.locale AND p.policy_revision=NEW.policy_revision AND p.publication_state='PUBLISHED' AND (p.references_json<>NEW.references_json OR p.policy_digest<>NEW.policy_digest OR p.publication_state<>NEW.publication_state)) BEGIN SELECT RAISE(ABORT,'community_policy_pair_immutable'); END;